  `status` enum('open','active','closed','pending') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'open' COMMENT 'Trạng thái hội thoại',
  `created_at` timestamp NULL DEFAULT NULL,
